R=[
(2474,"टॉर्टिला बीफ़ रोलअप, कम प्रोटीन","क्या आप वही पुराने सैंडविच का विकल्प ढूँढ रहे हैं? कैलिफ़ोर्निया की डीवीटा रीनल डाइटिशियन सारा के पास टॉर्टिला बीफ़ रोलअप (कम प्रोटीन) की रेसिपी है जो मज़ेदार, स्वादिष्ट और किडनी आहार के लिए अनुशंसित है।","2","1 रोलअप या 4 टुकड़े",
["2 मैदे के टॉर्टिला, 6″ आकार के","2 बड़े चम्मच फेंटा हुआ क्रीम चीज़","2 औंस रोस्ट बीफ़, पका हुआ","1/4 कप लाल प्याज़, कटा हुआ","1/4 शिमला मिर्च (लाल, पीली या हरी), पट्टियों में कटी हुई","8 खीरे के स्लाइस","2 रोमेन लेट्यूस के पत्ते","1 छोटा चम्मच Mrs. Dash® हर्ब सीज़निंग"],
["टॉर्टिला पर क्रीम चीज़ फैलाएँ।","हर टॉर्टिला पर रोस्ट बीफ़, लाल प्याज़, शिमला मिर्च की पट्टियों, खीरे और लेट्यूस की आधी-आधी मात्रा परतों में रखें।","Mrs. Dash® हर्ब सीज़निंग छिड़कें।","जेलीरोल की तरह लपेट लें।","हर टॉर्टिला को 4 टुकड़ों में काटें, या साबुत परोसें।"],
["फेंटा हुआ क्रीम चीज़ सामान्य क्रीम चीज़ की तुलना में आसानी से फैलता है।","सोडियम की मात्रा की तुलना करने के लिए टॉर्टिला के लेबल देखें और सबसे कम सोडियम वाला ब्रांड चुनें।"],
["1 मांस","1 स्टार्च","1 सब्ज़ी, कम पोटैशियम","1/2 वसा"]),
(2475,"मेडिटेरेनियन सूप जार","छोले, कम सोडियम वाले जैतून, शिमला मिर्च और प्याज़ को लहसुन-जड़ी-बूटी के मिश्रण और मलाईदारी के लिए थोड़े से रिकोटा के साथ पकाकर एक मेसन जार में रखा जाता है, जब तक कि गरम करके खाने का समय न हो। ब्रिटनी का मेडिटेरेनियन सूप जार दिल के लिए सेहतमंद, कम सोडियम वाला और फाइबर से भरपूर है।","1","1 सूप जार",
["3 बड़े कम सोडियम वाले काले जैतून","1/3 कप बिना नमक मिलाए डिब्बाबंद छोले","1/2 कप फ्रोज़न या ताज़ी शिमला मिर्च और प्याज़ की पट्टियाँ","1/2 बड़ा चम्मच Mrs. Dash® Garlic & Herb सीज़निंग मिश्रण","1/2 छोटा चम्मच काली मिर्च","1 छोटा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/8 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स (वैकल्पिक)","1 बड़ा चम्मच फुल-क्रीम दूध का रिकोटा चीज़","1/2 कप कोलस्लॉ मिक्स"],
["काले जैतून को काट लें। छोले धो लें।","सारी सामग्री को लिखे गए क्रम में 16 औंस के काँच के जार में परतों में रखें।","पकाने और परोसने के लिए तैयार होने तक फ्रिज में रखें।","खाने से 15 मिनट पहले जार को फ्रिज से निकालें।","जार में 5 औंस उबलता पानी डालें, ढक्कन बंद करें और मिलाने के लिए हिलाएँ। सामग्री को बिना खोले जार में 2 मिनट रहने दें।","जार की सामग्री को गहरे, चौड़े कटोरे में डालें। आनंद लें!"],
["कम नमक वाले क्रैकर या अपने पसंदीदा रोल या ब्रेड के साथ परोसें।","यदि किराने की दुकान में कम सोडियम वाले जैतून न मिलें, तो वे ऑनलाइन उपलब्ध हैं।","फुल-क्रीम दूध का रिकोटा चीज़ सूप में मलाईदारी जोड़ता है और कम वसा वाले या स्किम रिकोटा चीज़ की तुलना में इसमें सोडियम कम होता है।","स्वाद को और बढ़ाने के लिए थोड़ा पेस्टो डालें। डीवीटा की बेसिल पेस्टो रेसिपी देखें।"],
["1 स्टार्च","2 सब्ज़ी, कम और मध्यम पोटैशियम","1-1/2 वसा"]),
(2479,"डरहम साउदर्न-स्टाइल चिकन सलाद","नॉर्थ कैरोलिना की रीनल डाइटिशियन सू किडनी के अनुकूल डरहम साउदर्न-स्टाइल चिकन सलाद की अपनी स्वादिष्ट रेसिपी साझा करती हैं, जो सैंडविच की फिलिंग या सलाद के रूप में बिल्कुल सही है।","6","1/2 कप",
["2 कप पका हुआ चिकन","1/2 मध्यम सफ़ेद प्याज़","3/4 कप सेलरी","1/2 कप मेयोनेज़","1 बड़ा चम्मच सरसों (मस्टर्ड)","2 बड़े चम्मच सिरका","2 बड़े चम्मच चीनी"],
["चिकन को छोटे टुकड़ों में काटें। प्याज़ को बारीक काटें और सेलरी के स्लाइस बना लें।","चिकन, प्याज़ और सेलरी को एक कटोरे में मिलाएँ।","एक अलग कटोरे में मेयोनेज़, सरसों, सिरका और चीनी मिलाएँ।","अच्छी तरह मिलाया हुआ मेयोनेज़ का मिश्रण चिकन में डालकर चलाएँ। परोसने तक फ्रिज में रखें।"],
["सैंडविच बनाएँ या मिले-जुले पत्तेदार साग के ऊपर सलाद की तरह परोसें।","कम वसा के लिए कम वसा वाली मेयोनेज़ इस्तेमाल करें, लेकिन सोडियम ज़्यादा होगा: 11 ग्राम वसा, 210 कैलोरी, 256 mg सोडियम।","अपनी पसंद का सिरका इस्तेमाल करें, लेकिन यदि वह मसालेदार हो तो सोडियम की मात्रा जाँच लें।"],
["2-1/2 मांस","1/2 उच्च कैलोरी","1 वसा"]),
(2480,"कूल एन क्रंची चिकन सलाद","गरमियों के किसी तपते दिन के लिए किडनी के अनुकूल कूल एन क्रंची चिकन सलाद से बेहतर रेसिपी और क्या हो सकती है?","6","1/2 कप",
["2 कप चिकन, पका हुआ","1 बड़ा उबला अंडा","2 बड़े चम्मच प्याज़","1/4 कप सेलरी","1/4 कप कम वसा वाली मेयोनेज़","1 छोटा चम्मच ताज़ा नींबू का रस","1/2 छोटा चम्मच चीनी","1/4 छोटा चम्मच काली मिर्च"],
["चिकन को छोटे टुकड़ों में काटें या रेशे-रेशे कर लें। अंडा, प्याज़ और सेलरी काट लें।","सारी सामग्री को एक बड़े कटोरे में डालकर मिलाएँ।","ढककर रात भर या परोसने से कम से कम 2 घंटे पहले ठंडा करें।"],
["यदि चाहें तो इसे ब्रेड, रोल, क्रोसैं या पिटा ब्रेड में हरे पत्ते वाले लेट्यूस के साथ परोसें।"],
["2 मांस","1 वसा"]),
(2481,"टेक्स-मेक्स विंग्स","डीवीटा डाइटिशियन द्वारा तैयार किए गए, किडनी आहार के लिए ये टेक्स-मेक्स विंग्स आपके स्वाद की कलियों को ज़रूर जगा देंगे।","12","2 विंग्स",
["8 औंस डिब्बाबंद कटी हुई हरी मिर्च","1/2 कप बारबेक्यू सॉस","3/4 कप शहद","2 छोटे चम्मच लाल मिर्च पाउडर (चिली पाउडर)","1/3 छोटा चम्मच पिसा जीरा","24 चिकन विंग ड्रमेट"],
["ओवन को 400° F पर पहले से गरम करें।","चिकन विंग्स को छोड़कर सारी सामग्री एक बड़े कटोरे में मिलाएँ।","चिकन डालकर परत चढ़ाने के लिए मिलाएँ।","चिकन विंग्स को बेकिंग डिश में रखें और 30 से 35 मिनट बेक करें। पक गए हैं या नहीं जाँच लें।","विंग्स को गरम परोसें या परोसने तक ढके हुए वार्मिंग डिश या क्रॉक-पॉट में धीमी आँच (लो सेटिंग) पर रखें।"],
["ताज़े विंग ड्रमेट खरीदें। 1-1/4 पाउंड के पैकेट में लगभग 12 ड्रमेट होते हैं। न मिलने पर अपने कसाई से साबुत चिकन विंग्स को ड्रमेट के आकार में कटवाएँ।","इस रेसिपी में बिना हड्डी वाले चिकन के टुकड़े भी इस्तेमाल किए जा सकते हैं। 20 मिनट बाद जाँचें कि पके हैं या नहीं।","सबसे कम सोडियम वाला बारबेक्यू सॉस चुनें, या बाज़ार के बारबेक्यू सॉस की जगह DaVita.com की ज़ेस्टी बारबेक्यू सॉस रेसिपी के साथ परोसें। उसमें सोडियम बहुत कम होता है।","हरी मिर्च का सबसे कम सोडियम वाला ब्रांड ढूँढें। अलग-अलग ब्रांडों में सोडियम बहुत अलग होता है।"],
["1-1/2 मांस","1/2 वसा","1-1/2 उच्च कैलोरी"]),
(2482,"पुदीना वाली नींबू पानी (मिंटेड लेमोनेड)","मिंटेड लेमोनेड के एक ताज़गी भरे गिलास से अपनी प्यास बुझाएँ। किडनी के अनुकूल इस रेसिपी में नींबू, पुदीने और स्वीटनर का सही संतुलन है, जो एक स्वादिष्ट पेय बनाता है जिसे आप पूरी गरमियों में चुस्कियों के साथ पिएँगे।","5","6 औंस (3/4 कप)",
["6 बड़े चम्मच ताज़ा नींबू का रस","1/2 कप चीनी","6 पुदीने के पत्ते","3-1/2 कप ठंडा पानी"],
["1 क्वार्ट के जग में नींबू का रस, चीनी और पुदीने के पत्ते मिलाएँ। जग भरने के लिए 3-1/2 कप ठंडा पानी डालें।","ठंडा होने तक फ्रिज में रखें।","6 औंस के गिलास में पुदीने की टहनी से सजाकर परोसें।"],
["पुदीने का ज़्यादा स्वाद पाने के लिए पुदीने के पत्तों को कुचल लें।","कार्बोहाइड्रेट और कैलोरी घटाने के लिए चीनी की जगह Splenda® स्वीटनर इस्तेमाल करें (12 पैकेट या 1/2 कप Splenda® दानेदार)। कैलोरी घटकर 16 और कार्बोहाइड्रेट 4 ग्राम रह जाता है।"],
["1/2 फल, कम पोटैशियम","1 उच्च कैलोरी"]),
(2483,"न्यू इंग्लैंड लॉबस्टर रोल्स","बढ़िया लॉबस्टर रोल की कुंजी उसे सरल रखना है। मेयोनेज़, नींबू के रस, सेलरी और हॉट सॉस के साथ मिले लॉबस्टर से भरे टोस्टेड बन इन न्यू इंग्लैंड लॉबस्टर रोल्स को शानदार बनाते हैं!","4","1 लॉबस्टर रोल",
["12 औंस लॉबस्टर का मांस","1/3 कप सेलरी","3 बड़े चम्मच मेयोनेज़","3 बड़े चम्मच नींबू का रस","1/4 छोटा चम्मच हॉट सॉस","4 ऊपर से कटे हुए हॉटडॉग रोल","2 बड़े चम्मच बिना नमक का मक्खन","4 नींबू की फाँकें"],
["लॉबस्टर को तब तक भाप में पकाएँ जब तक मांस सफ़ेद अपारदर्शी न हो जाए, लगभग 5 से 6 मिनट। ठंडा होने दें, फिर लॉबस्टर को निवाले के आकार के टुकड़ों में काटें। लॉबस्टर पकते समय सेलरी को बारीक काट लें।","मेयो, सेलरी, नींबू का रस और हॉट सॉस मिलाएँ। लॉबस्टर का मांस डालें और परत चढ़ाने के लिए मिलाएँ।","बन को बीच से काटकर मक्खन लगाएँ। कड़ाही में टोस्ट करें।","लॉबस्टर के मिश्रण को 4 बन में बाँटकर लॉबस्टर रोल बनाएँ। नींबू की फाँकों के साथ परोसें।"],
["यदि ऊपर से कटे हॉटडॉग रोल न मिलें तो सामान्य हॉटडॉग बन खरीदें।","ताज़ा या फ्रोज़न लॉबस्टर का मांस या लॉबस्टर टेल ढूँढें, या साबुत लॉबस्टर पकाएँ। 6 औंस की दो लॉबस्टर टेल बहुत अच्छी रहती हैं।","लॉबस्टर के मांस में प्राकृतिक रूप से सोडियम ज़्यादा होता है। अपनी सोडियम सीमा के भीतर रहने के लिए बाकी भोजन में कम सोडियम वाले खाद्य पदार्थ चुनें।"],
["2 मांस","1-1/2 स्टार्च","1 वसा"]),
(2485,"दो बार बेक किया सेब का केक","किडनी के अनुकूल दो बार बेक किए सेब के केक के साथ बेक किए सेबों, दालचीनी और केक की खुशबू का आनंद लें।","12","केक का 1/12 टुकड़ा",
["2/3 कप दानेदार चीनी और 3 बड़े चम्मच","1 कप मैदा, बिना छना","7 बड़े चम्मच मार्जरीन","1 छोटा चम्मच बेकिंग सोडा","1 छोटा चम्मच वनीला एक्सट्रैक्ट","2 बड़े अंडे","4 बड़े खट्टे सेब","1 छोटा चम्मच पिसी दालचीनी"],
["ओवन को 350° F पर पहले से गरम करें। 9 इंच के स्प्रिंगफॉर्म पैन में चिकनाई लगाएँ।","4 बड़े चम्मच मार्जरीन को टुकड़ों में काटें। फ़ूड प्रोसेसर में मेटल ब्लेड लगाकर, फ़ूड प्रोसेसर के कटोरे में 2/3 कप चीनी, मैदा, 4 बड़े चम्मच मार्जरीन, बेकिंग सोडा, वनीला और एक अंडा डालें। तब तक प्रोसेस करें जब तक मिश्रण कॉर्नमील जैसा न दिखे। मिश्रण को अच्छी तरह चिकनाई लगे पैन की तली में फैला दें।","सेबों को छीलें, चार हिस्सों में काटें और बीज निकाल दें। फ़ूड प्रोसेसर में स्लाइसिंग डिस्क लगाएँ और सेब के चौथाई टुकड़ों को फ़ीड ट्यूब में खड़ा रखें। पुशर पर मध्यम दबाव डालते हुए स्लाइस करें।","सेब के स्लाइस को क्रम्ब वाले मिश्रण के ऊपर परतों में सजाएँ। 45 मिनट बेक करें।","केक के बेक होने के दौरान, मेटल ब्लेड वाले फ़ूड प्रोसेसर के कटोरे में बची हुई 3 बड़े चम्मच चीनी, बचा हुआ 3 बड़े चम्मच (पिघला) मार्जरीन, दालचीनी और एक अंडा डालें। मिश्रण के चिकना होने और चीनी के घुल जाने तक प्रोसेस करें। मिश्रण को सेबों के ऊपर चम्मच से डालें और 30 मिनट और बेक करें, या जब तक ऊपर का हिस्सा कड़ा न हो जाए।"],
["सुझाई गई सेब की किस्में हैं कॉर्टलैंड, पिपिन, रोम या आपकी अपनी पसंदीदा।","यदि आपके पास फ़ूड प्रोसेसर नहीं है, तो केक और टॉपिंग मिलाने के लिए ब्लेंडर इस्तेमाल करें।"],
["1/2 फल, कम पोटैशियम","1/2 स्टार्च","1-1/2 वसा","1 उच्च कैलोरी"]),
(2492,"बिना झंझट का माइक्रोवेव एग व्हाइट फ्रेंच टोस्ट","जहाँ शानदार रेस्तरां के शेफ़ को रेसिपी बनाते समय \"रचनात्मक\" कहा जाता है, वहीं एक रीनल डाइटिशियन उसी रचनात्मकता का इस्तेमाल किडनी के मरीज़ों को उनके सेहतमंद आहार का आनंद दिलाने में करती है। ओरेगन की डीवीटा डाइटिशियन सूज़न अपना स्वादिष्ट बिना झंझट का माइक्रोवेव एग व्हाइट फ्रेंच टोस्ट साझा करती हैं, एक शानदार कम चीनी, कम वसा वाला नाश्ता जिसे ठंडा करके ब्रेड पुडिंग की तरह भी खाया जा सकता है। दोगुना स्वादिष्ट!","1","1 कटोरा",
["1 स्लाइस ब्रेड","1 छोटा चम्मच बिना नमक का मक्खन, नरम किया हुआ","1/2 कप अंडे की सफ़ेदी","2 बड़े चम्मच शुगर-फ्री सिरप"],
["ब्रेड या इंग्लिश मफ़िन पर मक्खन लगाएँ। चौकोर टुकड़ों में काटें।","मक्खन लगे ब्रेड के टुकड़ों को माइक्रोवेव में रखने लायक कटोरे में रखें।","ब्रेड को ढकने के लिए अंडे की सफ़ेदी डालें।","ऊपर से सिरप छिड़कें।","1 मिनट माइक्रोवेव करें; अंडे की सफ़ेदी के किनारों को ऊपर धकेलें ताकि कच्चा अंडा किनारों तक पहुँच जाए।","एक मिनट और माइक्रोवेव करें या जब तक अंडा जम न जाए।"],
["फ्रेंच टोस्ट की तरह गरम परोसें या ठंडा करके ब्रेड पुडिंग की तरह खाएँ।","अंडे की सफ़ेदी कम से कम फॉस्फोरस या वसा के साथ उत्कृष्ट गुणवत्ता का प्रोटीन देती है।","चाहें तो 1/2 कप अंडे की सफ़ेदी की जगह 2 पूरे फेंटे हुए अंडे इस्तेमाल करें। इस बदलाव से पोषक तत्व बढ़कर 288 कैलोरी, 15 ग्राम वसा, 434 mg कोलेस्ट्रॉल और 226 mg फॉस्फोरस हो जाएँगे; सोडियम घटकर 353 mg रह जाएगा।","चाहें तो लाइट या शुगर-फ्री सिरप की जगह प्राकृतिक मेपल सिरप या दालचीनी वाली चीनी इस्तेमाल करें।","यह रेसिपी ब्रेड के एक स्लाइस की जगह इंग्लिश मफ़िन के आधे हिस्से के साथ भी अच्छी बनती है।"],
["2 मांस","1 स्टार्च","1/2 उच्च कैलोरी"]),
(2496,"क्लासिक हल्ला (चैला)","चैला (हल्ला) एक सादी खमीर वाली ब्रेड है जो सब्बाथ और यहूदी त्योहारों पर परोसी जाती है। मरियम की यह क्लासिक चैला आज़माएँ।","32","1 टुकड़ा (2 औंस)",
["7 कप मैदा","2 बड़े चम्मच सूखा बेकर का यीस्ट (खमीर)","6 बड़े चम्मच चीनी","2-1/2 कप गुनगुना पानी","1/2 कप वनस्पति तेल","2 छोटे चम्मच नमक","1 बड़ा अंडा"],
["मैदा, यीस्ट, चीनी, पानी और तेल को एक बड़े कटोरे में रखकर मिलाएँ। आटा गूँधें। जब गोला बन जाए तो नमक डालें। आटे को मैदा लगी सतह पर रखें और 10 मिनट तक गूँधते रहें, जब तक आटा चिकना और नरम न हो जाए और चिपचिपा न रहे।","कटोरे और आटे पर 1 से 2 छोटे चम्मच तेल लगाएँ। कटोरे को ढककर गरम जगह पर रखें जब तक आटा दोगुना न हो जाए (1 से 2 घंटे)।","फूले हुए आटे को कुछ मिनट गूँधें। आटे को 12 टुकड़ों में बाँटें और हर टुकड़े को गूँथने के लिए लगभग 10″ से 12″ लंबी रस्सी की तरह बेलें।","चैला बनाने के लिए बेली हुई 3 आटे की रस्सियों को आपस में गूँथ लें। बची हुई रस्सियों के साथ दोहराएँ ताकि 4 चैला बन जाएँ।","चैला को बेकिंग शीट या बेकिंग पैन पर रखें, ढक दें और आटे को फिर से फूलने दें, लगभग 40 मिनट।","ओवन को 350º F पर पहले से गरम करें। हर चैला पर फेंटा हुआ अंडा लगाएँ। लगभग 30 मिनट बेक करें, जब तक चैला सुनहरा भूरा न हो जाए। चैला को ओवन से और बेकिंग पैन से निकालें और वायर रैक पर ठंडा करें।"],
["4 लोफ़ के कुल 32 हिस्सों के लिए हर चैला को 8 हिस्सों में बाँटें।","चाहें तो बेक करने से पहले ऊपर से खसखस या तिल छिड़कें।","चैला को गूँथने और आकार देने के निर्देशों के लिए YouTube पर ऑनलाइन वीडियो देखें।"],
["1-1/2 स्टार्च","1/2 वसा"]),
(2498,"सोडा पॉप ब्रेड","सोडा पॉप ब्रेड आम क्विक ब्रेड नहीं है। इसमें नमकीन स्वादों के साथ मिला सोडा पॉप डाला जाता है, जो एक अनोखी ब्रेड बनाता है जो आपके स्वाद की कलियों को ज़रूर \"पॉप\" कर देगी।","12","1 स्लाइस",
["3 कप मैदा","1/2 कप दानेदार चीनी","2 छोटे चम्मच बेकिंग पाउडर","1/4 छोटा चम्मच नमक","2 बड़े अंडे","1 बड़ा चम्मच बारीक कटा लहसुन","12 औंस रूट बियर","1 छोटा चम्मच कायेन मिर्च"],
["ओवन को 350˚ F पर पहले से गरम करें।","एक मध्यम कटोरे में मैदा, चीनी, बेकिंग पाउडर और नमक मिलाएँ। अच्छी तरह मिलाएँ।","अंडे और लहसुन डालकर मिलाएँ। रूट बियर और कायेन मिर्च डालें। सारी सामग्री को अच्छी तरह मिलाएँ।","मिश्रण को चिकनाई लगे 9 x 5 इंच के ब्रेड लोफ़ पैन में डालें।","55 से 65 मिनट बेक करें। पैन से निकालने से पहले लोफ़ को ठंडा होने दें।"],
["यदि आपको तीखापन पसंद नहीं तो कायेन मिर्च कम डालें।","रूट बियर और कायेन मिर्च की जगह इनमें से कोई विकल्प आज़माएँ: 12 औंस जिंजर एल और 1/3 कप ताज़े कटे रोज़मेरी के पत्ते; या 12 औंस Orange Crush® या Orange Sunkist® सोडा और 1 बड़ा चम्मच पिसी तुलसी; या 12 औंस नींबू-लाइम सोडा और 1/2 कप ताज़ी कटी धनिया पत्ती।","रूट बियर, जिंजर एल, ऑरेंज सोडा और नींबू-लाइम सोडा में आम तौर पर फॉस्फोरस वाले एडिटिव्स नहीं होते। फिर भी, फॉस्फेट एडिटिव्स के लिए हमेशा सामग्री की सूची देखें।"],
["1-1/2 स्टार्च","1/2 उच्च कैलोरी"]),
(2499,"स्टफ्ड फ्रेंच टोस्ट","बचे हुए फ्रेंच ब्रेड को किडनी के अनुकूल एक स्वादिष्ट सुबह के भोजन, स्टफ्ड फ्रेंच टोस्ट, में बदलें, जिसे आप रात को पहले ही बना सकते हैं और सुबह बस ओवन में डाल दें।","8","1/8 रेसिपी",
["8 औंस क्रीम चीज़","1 पाउंड का एक दिन पुराना फ्रेंच ब्रेड का लोफ़","8 बड़े चम्मच जैली, कोई भी फ्लेवर","6 बड़े अंडे","1 कप 1% कम वसा वाला दूध","1 छोटा चम्मच वनीला एक्सट्रैक्ट"],
["ब्रेड के लोफ़ को 16 स्लाइस में काटें।","ब्रेड के हर स्लाइस पर 1 बड़ा चम्मच क्रीम चीज़ लगाएँ। उस पर 1 बड़ा चम्मच जैली लगाएँ और सैंडविच बनाने के लिए ऊपर ब्रेड का स्लाइस रखें। 8 सैंडविच बनने तक दोहराएँ।","9” x 13” के बेकिंग डिश पर नॉनस्टिक कुकिंग स्प्रे करें और 8 सैंडविच उसमें रखें।","अंडे फेंटें, फिर दूध और वनीला एक्सट्रैक्ट के साथ मिलाएँ। ब्रेड के स्लाइस पर डालें और उन्हें पलटकर बराबर परत चढ़ाएँ। ढककर रात भर फ्रिज में रखें।","ओवन को 350° F पर पहले से गरम करें। पैन को फॉइल से ढककर 1 घंटे बेक करें। बेकिंग के आख़िरी 5 मिनट में फॉइल हटा दें ताकि ऊपर का हिस्सा भूरा हो जाए।"],
["क्रीम चीज़ को कमरे के तापमान पर ले आएँ ताकि उसे फैलाना आसान हो।","परोसने के सुझाव: ऊपर से सिरप डालें, ताज़े फल और व्हिप्ड क्रीम से सजाएँ या पिसी चीनी छिड़कें।","यह रेसिपी प्रोटीन और कैलोरी का अच्छा स्रोत है, ऊर्जा से भरपूर नाश्ते के लिए बढ़िया विकल्प। फ्रेंच टोस्ट का यह अलग रूप आज़माएँ। बचे हुए ब्रेड का यह अच्छा उपयोग है। साथ ही, इस रेसिपी को रात को तैयार करने से सुबह के लिए बस बेक करके परोसना ही बचता है। यह ब्रंच के लिए बिल्कुल सही है।","ब्रेड की तुलना करें और कम सोडियम वाला ब्रांड चुनें।"],
["1 मांस","2 स्टार्च","2 वसा","1 उच्च कैलोरी"]),
(2500,"स्ट्रॉबेरी फ़ील्ड्स फ़ॉरएवर","स्ट्रॉबेरी फ़ील्ड्स फ़ॉरएवर सिर्फ़ बीटल्स के एक गाने का नाम नहीं है, यह कैलिफ़ोर्निया की डीवीटा रीनल डाइटिशियन सैंडी की साझा की हुई ताज़गी भरी स्ट्रॉबेरी डिश भी है। सैंडी की किडनी के अनुकूल स्ट्रॉबेरी फ़ील्ड्स फ़ॉरएवर रेसिपी ताज़े फलों की मीठी महक को चटपटे बाल्सामिक सिरके के साथ मिलाती है। यह बिना मेहनत की रेसिपी है जो अकेले भी परोसी जा सकती है, या सलाद, केक या फ्रोज़न मिठाई पर स्वागत योग्य टॉपिंग भी बन सकती है।","4","1/2 कप",
["3 कप ताज़ी स्ट्रॉबेरी","2 बड़े चम्मच बाल्सामिक सिरका","2 बड़े चम्मच Splenda® नो कैलोरी स्वीटनर, दानेदार","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च"],
["स्ट्रॉबेरी को डंठल सहित धोएँ (वरना पानी बीच के हिस्से में घुस जाएगा और स्ट्रॉबेरी गीली और पिलपिली हो जाएँगी)।","पेरिंग चाकू से डंठल हटा दें।","स्ट्रॉबेरी को आधा-आधा काट लें।","स्ट्रॉबेरी को एक कटोरे में रखें और सिरका डालें, फिर ऊपर से Splenda® छिड़कें।","धीरे से मिलाएँ।","ढककर कुछ घंटे, बेहतर हो कि रात भर, फ्रिज में रखें।","परोसने से ठीक पहले स्ट्रॉबेरी के ऊपर काली मिर्च पीसकर डालें।"],
["ठंडक हटाने के लिए परोसने से 10 मिनट पहले स्ट्रॉबेरी को फ्रिज से निकाल लें।","इसे एंजेल फ़ूड केक पर टॉपिंग के रूप में परोसा जा सकता है।","चाहें तो Splenda® की जगह चीनी या दूसरे टेबलटॉप स्वीटनर इस्तेमाल करें।"],
["1 फल, मध्यम पोटैशियम"]),
(2502,"क्रीम चीज़ फ्रॉस्टिंग के साथ ताज़ा सेब का केक","सेब, दालचीनी, पीकन और क्रीम चीज़ सब मिलकर किडनी के अनुकूल एक स्वादिष्ट केक बनाते हैं, जिसके लिए बेव और कैलिफ़ोर्निया की रीनल डाइटिशियन नैंसी का धन्यवाद। इसे रोज़ की मिठाई के रूप में या किसी खास अवसर पर परोसें। आपके मेहमान कभी अंदाज़ा नहीं लगा पाएँगे कि यह कम सोडियम, कम पोटैशियम और कम फॉस्फोरस वाला केक है।","20","2-1/4\" x 2-1/2\"",
["2 बड़े अंडे","3/4 कप कैनोला तेल","2 कप दानेदार चीनी","3 छोटे चम्मच वनीला","4 मध्यम सेब","2 कप मैदा","2 छोटे चम्मच दालचीनी","2 छोटे चम्मच बेकिंग सोडा","1 कप कटे हुए पीकन","8 औंस क्रीम चीज़","2 कप पिसी हुई चीनी (पाउडर शुगर)"],
["ओवन को 350º F पर पहले से गरम करें। 9″ x 13″ के बेकिंग पैन पर नॉन-स्टिक कुकिंग स्प्रे करें।","क्रीम चीज़ को नरम होने के लिए बाहर रखें। सेबों को छीलें, बीच का हिस्सा निकालें और काट लें।","अंडे, तेल, चीनी और 2 छोटे चम्मच वनीला मिलाएँ। सेब डालकर चलाएँ।","एक अलग कटोरे में मैदा, दालचीनी, बेकिंग सोडा और पीकन मिलाएँ।","सूखे मिश्रण को सेब के मिश्रण में डालकर मिलाएँ।","बेकिंग पैन में डालें और एक घंटे बेक करें। ठंडा होने दें।","आइसिंग के लिए मिक्सर से क्रीम चीज़, पिसी हुई चीनी और बचा हुआ वनीला मिलाएँ।","केक के ठंडा होने के बाद आइसिंग को केक पर फैलाएँ।"],
["मधुमेह वाले लोग कैलोरी घटाकर 252 और कार्बोहाइड्रेट 33 ग्राम करने के लिए आइसिंग छोड़ सकते हैं। इसे 2 कार्बोहाइड्रेट विकल्प गिनें।","वसा घटाने के लिए आप आधे तेल की जगह बिना मीठी सेब की प्यूरी (ऐपलसॉस) इस्तेमाल कर सकते हैं।","पीकन में पोटैशियम और फॉस्फोरस ज़्यादा होता है। यदि सुझाए गए हिस्से का पालन किया जाए तो केक के एक टुकड़े में इसकी मात्रा बहुत कम होती है। वरना आप पीकन घटाकर 1/2 कप कर सकते हैं या छोड़ सकते हैं।"],
["1 स्टार्च","1 फल, कम पोटैशियम","3 वसा","1 उच्च कैलोरी"]),
(2503,"क्रीमी पास्ता प्राइमावेरा","कैलिफ़ोर्निया की डीवीटा रीनल डाइटिशियन मैरी को अलग-अलग देशों के व्यंजन आज़माना और उन्हें किडनी के अनुकूल बनाना पसंद है ताकि उनके डायलिसिस के मरीज़ भी उन्हें खा सकें। यदि आपको इतालवी स्वाद पसंद है, तो मैरी का क्रीमी पास्ता प्राइमावेरा आज़माएँ।","6","1 कप",
["1 कप गाजर","8 औंस क्रीम चीज़","1/4 कप हरा प्याज़","8 औंस साबुत गेहूँ का बो टाई पास्ता, बिना पका","1 कप ब्रोकली के फूल","3/4 कप Rice Dream® Original Classic राइस ड्रिंक","2 बड़े चम्मच कसा हुआ पार्मेसन चीज़","1 छोटा चम्मच इटैलियन सीज़निंग","1/4 छोटा चम्मच लहसुन पाउडर"],
["गाजर के स्लाइस काटें, हरे प्याज़ को काटें और क्रीम चीज़ को चौकोर टुकड़ों में काट लें।","पैकेट पर बताए अनुसार पास्ता तैयार करें (नमक के बिना)। पकाने के आख़िरी 5 मिनट में ब्रोकली और गाजर को पानी में डालें। निथार लें।","एक बड़े सॉसपैन में क्रीम चीज़, Rice Dream®, पार्मेसन चीज़, प्याज़ और मसाले मिलाएँ; धीमी आँच पर क्रीम चीज़ पिघलने और मिश्रण अच्छी तरह मिलने तक पकाएँ, बार-बार चलाते रहें।","पास्ता और सब्ज़ियों को एक साथ मिलाएँ; हल्के से मिलाएँ और गरम परोसें।"],
["ज़्यादा प्रोटीन वाले व्यंजन के लिए चिकन या झींगे डालें।","ताज़ी सब्ज़ियों की जगह फ्रोज़न ब्रोकली और गाजर इस्तेमाल की जा सकती है।","फ़ोर्टिफ़ाइड राइस मिल्क में फॉस्फोरस और कैल्शियम मिलाया जाता है। बिना फ़ोर्टिफ़ाइड उत्पाद ढूँढें।"],
["2 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम","2 वसा"]),
(2505,"घर के बने हम्मस के साथ फ्लैटब्रेड वेजी रैप","इस रैप में सुंदर सब्ज़ियाँ हैं और साथ में एक अनोखा और आसान घर का बना हम्मस है। यह ज़रूर आपकी नई पसंदीदा रेसिपी बनेगी।","2","1 रैप",
["1/4 कप लाल प्याज़","2 चेरी टमाटर","1/2 मध्यम शिमला मिर्च","1/2 बड़ी गाजर","1 लहसुन की कली","2 ग्रीक फ्लैट ब्रेड","1 बड़ा चम्मच सादा ग्रीक योगर्ट","1/2 छोटा चम्मच पिसी काली मिर्च","1 बड़ा चम्मच जैतून का तेल","1 बड़ा चम्मच ताहिनी","1 बड़ा चम्मच नींबू का रस","1/2 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच लहसुन पाउडर","1/4 कप ताज़ा बेबी पालक","1 बड़ा चम्मच फ़ेटा चीज़ का चूरा"],
["लाल प्याज़ के स्लाइस बनाएँ और चेरी टमाटर को चार हिस्सों में काटें। लाल शिमला मिर्च और गाजर को पतली पट्टियों में काटें। लहसुन की कली को बारीक काट लें।","फ्लैट ब्रेड को एक-एक करके गरम पैन में मध्यम आँच पर हर तरफ़ 3-4 मिनट गरम करें।","एक कटोरे में कटा हुआ लहसुन, सादा ग्रीक योगर्ट, पिसी काली मिर्च, जैतून का तेल, ताहिनी, नींबू का रस, पिसा जीरा और लहसुन पाउडर फेंटकर मिलाएँ।","सॉस को हर पिटा ब्रेड पर बराबर फैलाएँ।","हर फ्लैट ब्रेड पर प्याज़, टमाटर, शिमला मिर्च, गाजर और पालक की परतें लगाएँ, दोनों फ्लैट ब्रेड में बराबर बाँटकर।","सब्ज़ियों के ऊपर फ़ेटा चीज़ छिड़कें और फ्लैटब्रेड को सब्ज़ियों के चारों ओर मोड़ें या लपेटें।"],
["यदि ग्रीक फ्लैट ब्रेड उपलब्ध न हो तो दूसरी तरह की फ्लैट ब्रेड इस्तेमाल की जा सकती है। यदि आप कम कार्बोहाइड्रेट वाले आहार पर हैं तो खाद्य लेबल पर सबसे कम सोडियम और कार्बोहाइड्रेट वाला ब्रांड देखें।","बचे हुए ग्रीक योगर्ट को डिप के रूप में या खट्टी क्रीम की जगह इस्तेमाल करें। बची हुई गाजर और शिमला मिर्च को ग्रीक योगर्ट में डुबोकर नाश्ते के रूप में खाया जा सकता है।"],
["1 स्टार्च","1-1/2 सब्ज़ी, मध्यम पोटैशियम","2-1/2 वसा"]),
(2507,"खीरा-गाजर सलाद","खीरा-गाजर सलाद DaVita.com के सलाद अनुभाग की एक ठंडी, कुरकुरी और किडनी के अनुकूल रेसिपी है।","4","1/2 कप",
["1/4 कप बिना मसाले वाला राइस विनेगर","1 छोटा चम्मच चीनी","1/2 छोटा चम्मच जैतून का तेल","1/8 छोटा चम्मच काली मिर्च","1/2 खीरा","1 कप गाजर","2 बड़े चम्मच हरा प्याज़","2 बड़े चम्मच लाल शिमला मिर्च","1/2 छोटा चम्मच Mrs. Dash® Italian Medley सीज़निंग मिश्रण"],
["एक मध्यम कटोरे में राइस विनेगर, चीनी, जैतून का तेल और काली मिर्च मिलाएँ। फेंटने वाले चम्मच (व्हिस्क) से चलाएँ।","1/2 खीरे को खड़ी लंबाई में आधा काटें, बीज निकालें और स्लाइस बना लें। गाजर और हरे प्याज़ को काटें। शिमला मिर्च को बारीक काटें।","सिरके के मिश्रण में गाजर, प्याज़, लाल शिमला मिर्च, खीरा और Mrs. Dash डालें; परत चढ़ाने के लिए मिलाएँ।","ढककर 30 मिनट ठंडा करें।"],
["बिना मसाले वाला राइस विनेगर चुनें या न मिलने पर सेब का सिरका इस्तेमाल करें। मसालेदार राइस विनेगर से बचें, क्योंकि उसके सिर्फ़ एक बड़े चम्मच में 240 मिलीग्राम सोडियम होता है।"],
["1 सब्ज़ी, मध्यम पोटैशियम"]),
(2508,"एप्पल फ्रिटर रिंग्स","एप्पल फ्रिटर किसे पसंद नहीं? अगली बार नाश्ता बनाते समय किडनी के अनुकूल एप्पल फ्रिटर रिंग्स का आनंद लें।","20","1 फ्रिटर",
["4 बड़े, खट्टे पकाने वाले सेब","1 कप सफ़ेद मैदा","6 बड़े चम्मच चीनी (बँटी हुई)","1 छोटा चम्मच बेकिंग पाउडर","1 बड़ा अंडा, फेंटा हुआ","1/3 कप 1% कम वसा वाला दूध","1/3 कप बादाम का दूध","1 छोटा चम्मच कैनोला तेल","डीप फ्राई करने के लिए तेल, लगभग 3/4 कप","1/2 छोटा चम्मच दालचीनी"],
["सेबों को छीलकर बीच का हिस्सा निकाल दें। हर सेब को 5 छल्लों में काटें, हर छल्ला लगभग 1/2″ मोटा हो।","एक मिक्सिंग बाउल में मैदा, 2 बड़े चम्मच चीनी और बेकिंग पाउडर को छानकर मिलाएँ।","एक अलग कटोरे में अंडा, दूध, बादाम का दूध और 1 छोटा चम्मच तेल मिलाएँ।","अंडे के मिश्रण को सूखी सामग्री में डालें और बस मिलने तक चलाएँ।","कम से कम 2″ गहरी कड़ाही में 1″ कुकिंग ऑयल को 375º F तक गरम करें।","सेब के स्लाइस को एक-एक करके घोल में डुबोएँ। गरम तेल में लगभग 1-1/2 मिनट तक सुनहरा भूरा होने तक तलें। कागज़ के तौलिये पर निथार लें।","बची हुई 1/4 कप चीनी को दालचीनी के साथ मिलाकर फ्रिटर पर छिड़कें। गरम परोसें।"],
["डोनट की दुकान के एप्पल फ्रिटर में लगभग 300 mg सोडियम होता है, जबकि इस रेसिपी के हर फ्रिटर में 33 mg।","चाहें तो चीनी की जगह Splenda® दानेदार चीनी का विकल्प इस्तेमाल किया जा सकता है।"],
["1/2 स्टार्च","1/2 फल","2 वसा"]),
]
